create table account (active bit not null, created_at datetime(6) not null, record_version bigint not null, updated_at datetime(6), code varchar(30) not null, created_by varchar(50), updated_by varchar(50), name varchar(255) not null, type varchar(255) not null, primary key (code)) engine=InnoDB;
