create table brands (is_active bit not null, created_at datetime(6) not null, id bigint not null auto_increment, record_version bigint not null, updated_at datetime(6), code varchar(50) not null, created_by varchar(50), updated_by varchar(50), name varchar(150) not null, description TEXT, primary key (id)) engine=InnoDB;
create table categories (is_active bit not null, created_at datetime(6) not null, id bigint not null auto_increment, record_version bigint not null, updated_at datetime(6), code varchar(20) not null, created_by varchar(50), updated_by varchar(50), name varchar(100) not null, description TEXT, primary key (id)) engine=InnoDB;
create table credit_notes (amount decimal(38,2) not null, applied_amount decimal(38,2) not null, issue_date date not null, created_at datetime(6), customer_id bigint not null, id bigint not null auto_increment, sales_return_id bigint not null, updated_at datetime(6), status varchar(30) not null, created_by varchar(50), credit_note_number varchar(50) not null, updated_by varchar(50), primary key (id)) engine=InnoDB;
create table credit_allocation (amount decimal(15,2) not null, reversed bit not null, credit_note_id bigint not null, id bigint not null auto_increment, invoice_id bigint not null, primary key (id)) engine=InnoDB;
create table customer_group_mappings (customer_id bigint not null, group_id bigint not null, primary key (customer_id, group_id)) engine=InnoDB;
create table customer_groups (is_active bit not null, assigned_staff_id bigint, created_at datetime(6) not null, id bigint not null auto_increment, record_version bigint not null, updated_at datetime(6), group_code varchar(30) not null, created_by varchar(50), updated_by varchar(50), group_name varchar(100) not null, description varchar(255), primary key (id)) engine=InnoDB;
create table customers (credit_limit decimal(38,2) not null, current_balance decimal(38,2) not null, is_active bit not null, created_at datetime(6) not null, customer_group_id bigint, delivery_route_id bigint, id bigint not null auto_increment, record_version bigint not null, updated_at datetime(6), customer_code varchar(20) not null, phone varchar(30), created_by varchar(50), updated_by varchar(50), contact_person varchar(100), email varchar(100), name varchar(150) not null, address TEXT, primary key (id)) engine=InnoDB;
create table deliveries (end_odometer float(53), scheduled_date date not null, start_odometer float(53), total_amount decimal(12,2), total_invoices_count integer, trip_duration_minutes integer, assistant_staff_id bigint not null, cancellation_date datetime(6), created_at datetime(6) not null, departure_time datetime(6), driver_id bigint not null, id bigint not null auto_increment, record_version bigint not null, return_time datetime(6), route_id bigint, updated_at datetime(6), vehicle_id bigint, warehouse_id bigint, status varchar(30) not null, created_by varchar(50), delivery_number varchar(50) not null, updated_by varchar(50), vehicle_number varchar(50), gps_tracking_code varchar(100), cancellation_reason TEXT, gps_last_location varchar(255), notes TEXT, primary key (id)) engine=InnoDB;
create table delivery_routes (estimated_distance_km float(53), estimated_duration_minutes integer, is_active bit not null, assigned_staff_id bigint, created_at datetime(6) not null, id bigint not null auto_increment, record_version bigint not null, updated_at datetime(6), route_code varchar(30) not null, created_by varchar(50), updated_by varchar(50), area varchar(100), delivery_days varchar(100), route_name varchar(100) not null, end_location varchar(150), start_location varchar(150), description TEXT, primary key (id)) engine=InnoDB;
create table document_sequences (year integer not null, created_at datetime(6), current_sequence bigint not null, id bigint not null auto_increment, updated_at datetime(6), prefix varchar(10) not null, document_type varchar(30) not null, primary key (id)) engine=InnoDB;
create table fiscal_year (closed bit not null, fiscal_year integer not null, primary key (fiscal_year)) engine=InnoDB;
create table grn_items (quantity_received decimal(38,2) not null, total_cost decimal(38,2) not null, unit_cost decimal(38,2) not null, created_at datetime(6), grn_id bigint not null, id bigint not null auto_increment, product_id bigint not null, notes varchar(255), primary key (id)) engine=InnoDB;
create table grns (received_date date not null, total_amount decimal(38,2) not null, cancelled_at datetime(6), created_at datetime(6) not null, id bigint not null auto_increment, purchase_order_id bigint, record_version bigint not null, supplier_id bigint not null, updated_at datetime(6), warehouse_id bigint not null, status varchar(30) not null, created_by varchar(50), grn_number varchar(50) not null, updated_by varchar(50), cancelled_by varchar(100), supplier_invoice_number varchar(100), cancel_reason TEXT, notes TEXT, primary key (id)) engine=InnoDB;
